def factorial(n):
    if n == 0:
        return 1
    return n * factorial(n - 1)

print(factorial(4))

def fact_a(n):
    if n == 1:
        return 1
    return n * fact_a(n - 1)

def fact_b(n):
    if n == 0:
        return 0
    return n * fact_b(n - 1)

def power(x, n):
    if n == 0:
        return 1
    half = power(x, n // 2)
    if n % 2 == 0:
        return half * half
    return half * half * x

print(power(2, 5))
